def main():
    resources=[]
    for key,title,url,domains,locators,scope in SOURCES:
        resources.append(dict(id='R-B06-'+key,title=title,authors=['Document maintainers'],edition='Passages accessed 2026-10-17',year=2026,kind='primary documentation',url=url,access='Public source passages inspected via web retrieval',domains=domains,role='primary',reason=scope,prerequisites=['Applicable B06 entry check'],locators=locators,assignable=True,inspection=dict(date='2026-10-17',method='Actual bounded web passage inspection, not search-result inference',scope=scope,limits='Only listed passages inspected. Execution, release compatibility, independent review and physical validation are separate.',evidence_urls=[url])))
