    gate=dict(status='passage-inspected',domains=['T'+str(n) for n in range(57,65)],research_input_sha256={path.relative_to(ROOT).as_posix():hashlib.sha256(path.read_bytes()).hexdigest()},reviewer='author agent; not independent human review',limits=['Published C17/C23 complete texts not inspected by this batch','No complete-book or entire-document inspection claimed','Hardware reference manuals, silicon errata, board revision and kernel/ISA release verification remain required before physical/guest claims'])
